{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "For general warranties, seek a higher cap"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "lower thresholds, a tipping rather than deductible basket, aggregation of related claims"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "a longer notification period—ideally covering at least two audit cycles"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Seek a 100% purchase-price cap for fundamental/title and capacity warranties, with a materially longer claim period, rather than the general regime."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Exclude fraud and fraudulent concealment from contractual protections, with careful drafting of whose conduct is covered."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure of public registers and all data-room material."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete constructive or “discoverable” knowledge and adviser-imputed knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make effective Bluefen consent, including satisfaction of applicable conditions, a Buyer-waivable condition precedent."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Arrange direct repayment through the completion funds flow and legally effective release arrangements at completion"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Include payment, a price deduction or a funded retention in the completion mechanics, supported by an indemnity for unpaid amounts."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "If unresolved, require a broader specific indemnity covering resulting ownership disputes, third-party claims, remediation and reasonable replacement or business-interruption losses, appropriately drafted."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for the pre-completion incident, including investigation, remediation and third-party exposure"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "If they are genuinely ordinary future operating costs, a price adjustment may not be justified"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Establish an express hierarchy distinguishing general warranties, fundamental/title warranties, tax claims, specific indemnities and completion/payment obligations."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is useful evidence, but the register alone does not complete verification."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax and wider IP protection are not “settled”"
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

